package in.kpmaster.mobile;
import android.content.Context;import java.nio.file.*;import org.json.*;
public class DemoTest{
 static void check(boolean b){if(!b)throw new AssertionError();}interface Action{void run()throws Exception;}static void reject(Action a)throws Exception{try{a.run();throw new AssertionError("Expected rejection");}catch(AssertionError e){throw e;}catch(Exception expected){}}
 static String read(Path d,String name)throws Exception{return new String(Files.readAllBytes(d.resolve(name+".json")),java.nio.charset.StandardCharsets.UTF_8);}
 public static void main(String[] args)throws Exception{Path d=Paths.get(args[0]);String id=new String(Files.readAllBytes(d.resolve("id.txt"))).trim();Context c=new Context(d.toString());DemoManager demo=new DemoManager(c,id);LicenseManager m=new LicenseManager(c,id);check(!m.hasStoredLicence());reject(()->m.importKey(read(d,"purchase")));reject(()->m.importLicence(read(d,"registration")));for(int i=0;i<15;i++){check(demo.use("kundali","same-chart-action-"+i,true).getBoolean("allowed"));check(demo.use("kundali","same-chart-action-"+i,true).getBoolean("known"));}check(!demo.use("kundali","sixteenth-action",true).getBoolean("allowed"));check(!m.importKey(read(d,"registration")));check(m.isRegistered());check(!m.hasStoredLicence());check(new DemoManager(c,id).status().getJSONObject("remaining").getInt("kundali")==0);for(int i=0;i<10;i++)check(demo.use("matchmaking","same-pair-action-"+i,true).getBoolean("allowed"));check(!demo.use("matchmaking","eleventh-action",true).getBoolean("allowed"));reject(()->m.importKey(read(d,"wrong-purchase")));check(m.importKey(read(d,"purchase")));m.active();check(m.hasStoredLicence());check(demo.status().getJSONObject("remaining").getInt("matchmaking")==0);reject(()->new DemoManager(c,"different-device").status());System.out.println("Android demo: PASS (15/10 limits, per-calculation counting, persistence, two-key activation)");}
}
